388	/// Reads and drops input until nothing arrives for `quiet` (at most `limit` events); returns how many were dropped.
389	fn drain_input(mut next: impl FnMut(Duration) -> io::Result<Option<TermEvent>>, quiet: Duration, limit: usize) -> usize {
390	    let mut dropped = 0;
391	    while dropped < limit && matches!(next(quiet), Ok(Some(_))) {
